import os,re,stat,tempfile
from pathlib import Path
p=Path(".env")
s=p.lstat()
if not stat.S_ISREG(s.st_mode): raise SystemExit("ROLE_CONFIG_NOT_REGULAR")
raw=p.read_bytes()
lines=raw.splitlines(keepends=True)
pat=re.compile(rb"^[ \t]*DEBUG_AI_ROLE_EXECUTION_MODE[ \t]*=")
idx=[i for i,l in enumerate(lines) if pat.match(l)]
if len(idx)>1: raise SystemExit("ROLE_CONFIG_DUPLICATE")
if idx:
 i=idx[0]
 old=lines[i].split(b"=",1)[1].strip().strip(b"\"'")
 if old not in (b"",b"legacy",b"six_role"): raise SystemExit("ROLE_CONFIG_UNEXPECTED")
 ending=b"\r\n" if lines[i].endswith(b"\r\n") else b"\n" if lines[i].endswith(b"\n") else b""
 lines[i]=b"DEBUG_AI_ROLE_EXECUTION_MODE=six_role"+ending
 new=b"".join(lines)
else:
 new=raw+(b"\n" if raw and not raw.endswith(b"\n") else b"")+b"DEBUG_AI_ROLE_EXECUTION_MODE=six_role\n"
if new!=raw:
 fd,tmp=tempfile.mkstemp(prefix=".role-mode-",dir=str(p.parent))
 try:
  with os.fdopen(fd,"wb") as f:
   os.fchown(f.fileno(),s.st_uid,s.st_gid)
   os.fchmod(f.fileno(),stat.S_IMODE(s.st_mode))
   f.write(new);f.flush();os.fsync(f.fileno())
  if p.read_bytes()!=raw:raise SystemExit("ROLE_CONFIG_CONCURRENT_CHANGE")
  os.replace(tmp,p)
 finally:
  if os.path.exists(tmp): os.unlink(tmp)
assert p.read_bytes()==new
print("ROLE_CONFIG=six_role")
PY
